-- Generated by `make db-migration` from schema.prisma. Review before applying.
-- Explicit transaction: Prisma does not make migrations atomic on PostgreSQL.
-- Hand-written SQL (RLS policies, CHECK constraints, functions) goes ABOVE the final COMMIT.
BEGIN;

-- Security review fix: user-scoped read policies applied even inside a tenant context, so
-- withTenant(A, userId=U) also returned U's memberships/roles/organizations in other tenants.
-- They now apply ONLY when no organization context is set (withUser()); inside withTenant() a
-- session sees exactly one organization.
ALTER POLICY member_read ON "organizations"
  USING (NULLIF(current_setting('app.current_organization_id', true), '') IS NULL
         AND id IN (SELECT m.organization_id FROM organization_members m
                    WHERE m.user_id = NULLIF(current_setting('app.current_user_id', true), '')::uuid AND m.status = 'active'));
ALTER POLICY member_read ON "organization_roles"
  USING (NULLIF(current_setting('app.current_organization_id', true), '') IS NULL
         AND organization_id IN (SELECT m.organization_id FROM organization_members m
                                 WHERE m.user_id = NULLIF(current_setting('app.current_user_id', true), '')::uuid AND m.status = 'active'));
ALTER POLICY self_read ON "organization_members"
  USING (NULLIF(current_setting('app.current_organization_id', true), '') IS NULL AND user_id = NULLIF(current_setting('app.current_user_id', true), '')::uuid);

COMMIT;
